79	      }
80	    }
81	
82	    // Initialize cache (disk if stores array has items, memory otherwise)
83	    cacheInstance = createCache({
84	      stores,
85	      ttl: getCacheTtlMs(),
86	      refreshThreshold: 0, // Disable background refresh
87	    });
